UPDATE yh_jz_service_person


		service_state=#{state},


		start_service_time=#{begintime},


		acceptsituation=#{acceptsituation},


		end_service_time=(SELECT NOW()),


		satisfaction=#{satisfaction},


		returnvisit = #{returnvisit,jdbcType=INTEGER}


		finishi_doctor = #{usercode,jdbcType=INTEGER}


WHERE id=#{id};

UPDATE yh_jz_service_total_person t1 left join yh_jz_service_person t2 on t2.user_code = t1.user_code
SET t2.isrede = 2
where t1.doctor_code=#{usercode};
